import {canonicalSha256} from '../core/canonical-json.mjs';import {createDefaultTokenAccountingRegistry} from './token-accounting.mjs';
export class LazyToolRegistry{constructor(tools=[],registry=createDefaultTokenAccountingRegistry()){this.tools=new Map(tools.map(x=>[x.name,Object.freeze({...x})]));this.registry=registry;}async materialize({required=[],optional=[],budgetTokens,model='fallback'}={}){const selected=[];const omissions=[];let used=0;for(const name of [...new Set([...required,...optional])]){const tool=this.tools.get(name);if(!tool){if(required.includes(name))throw new Error(`Required tool unavailable: ${name}`);omissions.push({name,reason:'tool unavailable'});continue;}const cost=await this.registry.countToolSchemas(model,[tool]);if(used+cost>budgetTokens){if(required.includes(name))throw new Error(`Required tool schema exceeds context budget: ${name}`);omissions.push({name,reason:'optional tool schema exceeds budget',estimatedTokens:cost});continue;}selected.push(tool);used+=cost;}for(const name of [...this.tools.keys()].sort())if(!selected.some(x=>x.name===name)&&!omissions.some(x=>x.name===name))omissions.push({name,reason:'not selected by route'});const payload={schemaVersion:1,model,tools:selected,estimatedTokens:used,omitted:omissions.sort((a,b)=>a.name.localeCompare(b.name))};return Object.freeze({...payload,registryReceiptSha256:canonicalSha256(payload)});}}
